function savePosterEdits(){
  const a=state.artifacts.find(a=>a.id===modalContext.id);if(!a)return null;const p=readPosterForm();
  if(JSON.stringify(p)!==JSON.stringify(a.poster)){if(a.workId){const w=state.works.find(w=>w.id===a.workId);if(w)delete w.decisions.activity;}a.poster=p;a.status=a.staleReason?'stale':'review';delete a.approvedAt;a.updatedAt=new Date().toISOString();a.language=p.language;a.sections=[{label:'海报文案',text:p.headline+'\n'+p.subheadline}];save();}return a;
}
async function handleExtendedAction(act,data){
  if(act==='ai-status'){showModal('模型连接',ui.ai.provider==='demo'?'当前使用模板演示':'GitHub Copilot SDK',renderAIConnection(),btn('关闭','close-modal',null));return true;}
  if(act==='ai-check'){await refreshAIStatus();if(modalContext.type==='poster')return true;if(document.querySelector('.modal'))showModal('模型连接','GitHub Copilot SDK',renderAIConnection(),btn('关闭','close-modal',null));toast(ui.ai.message);return true;}
  if(act==='logout'){await logout();location.href='/login';return true;}
  if(act==='retry-task'){const t=state.tasks.find(t=>t.id===data.id);if(t)await startRun(t.kind,t.customerId,t.prompt,{previousArtifact:t.previousArtifact,preferredVehicleId:t.preferredVehicleId,campaignId:t.campaignId,languageOverride:t.languageOverride,posterStyle:t.posterStyle,workId:t.workId,needsPoster:t.needsPoster,cohort:t.cohort?.map(x=>({...x,revision:getCustomer(x.id).contextVersion}))});return true;}
  if(act==='new-poster'){const campaign=state.campaigns.find(p=>p.id===data.id)||state.campaigns.find(p=>ui.market==='all'||p.market===ui.market)||state.campaigns[0];const customer=state.customers.find(c=>c.market===campaign?.market)||state.customers[0];const a=createPoster({campaign,customer,workspaceName:state.settings.name});state.artifacts.unshift(a);save();render();posterModal(a.id);return true;}
  if(['poster-save','poster-approve','poster-svg','poster-png','poster-ai'].includes(act)){
    const a=savePosterEdits();if(!a)return true;
    if(act==='poster-save'){render();posterModal(a.id);toast('海报已保存到交付物。');return true;}
    if(act==='poster-approve'){if(!isArtifactCurrent(state,a)){toast('这张海报已过期，请从最新客户工作打开新版本。');return true;}a.status='approved';a.approvedAt=new Date().toISOString();save();render();posterModal(a.id);toast('海报审核通过，导出将移除草稿标记。');return true;}
    if(act==='poster-ai'){await startRun('campaign',a.customerId,`优化这张活动海报，保持已确认信息，使用 ${a.poster.language} 语言。请给出完整活动包和适合视觉排版的简短海报文案。当前海报内容：${JSON.stringify(a.poster)}`,{campaignId:a.campaignId,languageOverride:a.poster.language,posterStyle:{size:a.poster.size,theme:a.poster.theme}});return true;}
    try{if(act==='poster-svg')download(buildPosterSVG(a.poster,{approved:a.status==='approved'}),a.title+'.svg','image/svg+xml;charset=utf-8');else{toast('正在生成高清 PNG…');const blob=await posterToPNG(a.poster,{approved:a.status==='approved'});download(blob,a.title+'.png','image/png');}posterModal(a.id);}catch(error){toast(error.message);}return true;
  }
  return false;
}

function showModal(title, subtitle, body, footer = '', cls = '') {
  if (!document.querySelector('.overlay')) previousFocus = document.activeElement;
  document.querySelector('#overlay-root').innerHTML = `<div class="overlay ${cls==='drawer'?'drawer-overlay':''}" data-overlay="true"><section class="modal ${cls}" role="dialog" aria-modal="true" aria-labelledby="modal-title"><header class="modal-header"><div><h2 id="modal-title">${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div><button class="icon-btn" data-act="close-modal" aria-label="关闭窗口">${i('close')}</button></header><div class="modal-body">${body}</div>${footer?`<footer class="modal-footer">${footer}</footer>`:''}</section></div>`;
  document.body.style.overflow='hidden'; requestAnimationFrame(()=>(document.querySelector('.modal input:not([type=checkbox]), .modal textarea, .modal select')||document.querySelector('.modal button'))?.focus());
}
function closeModal() { document.querySelector('#overlay-root').innerHTML=''; document.body.style.overflow=''; modalContext={}; previousFocus?.isConnected&&previousFocus.focus(); }
