function generationPayload(task) {
  const c={...getCustomer(task.customerId)};c.memories=c.memories.filter(m=>!m.superseded);if(task.languageOverride)c.language=task.languageOverride;
  const w=state.works.find(w=>w.id===task.workId);
  return {kind:task.kind,prompt:task.prompt,customer:c,vehicles:state.vehicles,knowledge:state.knowledge,workspaceName:state.settings.name,preferredVehicleId:task.preferredVehicleId,campaign:state.campaigns.find(p=>p.id===task.campaignId),previousArtifact:task.previousArtifact,needsPoster:task.needsPoster,workflow:w?workflowContext(state,w):null,cohort:task.cohort,businessContext:businessContext(state,task.kind,c)};
}
function safeRender(){if(!document.querySelector('.modal')&&!document.activeElement?.matches?.('input,textarea,select'))render();}
async function completeTask(task){
  const c=getCustomer(task.customerId);task.customerRevision??=c.contextVersion;task.events??=[];
  task.events.push({title:'已读取工作区上下文',detail:c.memories.filter(m=>!m.superseded).length+' 条有效记忆；使用同市场车源。',at:new Date().toISOString()});
  const controller=new AbortController();runningRequests.set(task.id,controller);
  task.events.push({title:'已向模型服务提交请求',detail:'等待生成结果；可以停止。',at:new Date().toISOString()});save();safeRender();
  try{
    const a=await generateAIArtifact(generationPayload(task),{signal:controller.signal});
    const stale=task.status==='stale'||task.customerRevision!==getCustomer(task.customerId).contextVersion||task.cohort?.some(x=>getCustomer(x.id).contextVersion!==x.revision);
    if(task.status==='cancelled'||stale){if(stale){task.status='stale';task.error='生成期间客户资料变化，旧结果未加入有效交付物。';}save();safeRender();return null;}
    Object.assign(a,{customerRevision:task.customerRevision,workId:task.workId,cohort:task.cohort});
    state.artifacts.unshift(a);task.artifactId=a.id;task.title=a.title;task.status='review';delete task.error;
    task.events.push({title:'已收到并保存结构化交付物',detail:a.engine==='demo'?'结果来自明确启用的演示模板。':'模型返回结果，内容等待人工审核。',at:new Date().toISOString()});
    const w=state.works.find(w=>w.id===task.workId);
    if(task.kind==='campaign'||task.needsPoster){const poster=createPoster({campaign:state.campaigns.find(p=>p.id===task.campaignId),customer:getCustomer(task.customerId),workspaceName:state.settings.name,artifact:a});if(task.posterStyle)poster.poster={...poster.poster,...task.posterStyle};Object.assign(poster,{customerRevision:task.customerRevision,workId:task.workId,cohort:task.cohort});state.artifacts.unshift(poster);task.posterId=poster.id;if(w){const old=state.artifacts.find(x=>x.id===w.posterId);if(old){old.staleReason='新邀请材料已备好';if(old.status!=='contacted')old.status='stale';delete old.approvedAt;}w.posterId=poster.id;delete w.decisions.activity;}}
    if(w)logWork(w,'AI 材料已备好',a.title+'；具体内容需审核。');save();safeRender();return a;
  }catch(error){if(!['cancelled','stale'].includes(task.status)){task.status='failed';task.error=error.name==='TimeoutError'?'模型响应超时，请重试。':error.code?error.message:'无法连接模型服务，请检查网络后重试。';}task.events.push({title:'生成未完成',detail:task.error||'客户资料已变化',at:new Date().toISOString()});save();safeRender();return null;}
  finally{runningRequests.delete(task.id);}
}
async function startRun(kind,cid,prompt,extra={}) {
  if(!extra.background)closeModal();const c=getCustomer(cid);const task={id:uid('task'),title:c.name.split(' ')[0]+' · '+kindLabel(kind),customerId:cid,customerRevision:c.contextVersion,kind,prompt,status:'running',createdAt:new Date().toISOString(),...extra};
  state.tasks.unshift(task);const w=state.works.find(w=>w.id===extra.workId);if(w)w.aiTaskId=task.id;
  ui.taskId=task.id;save();if(!extra.background)navigate('workspace');const artifact=await completeTask(task);
  if(!extra.background)toast(artifact?(task.posterId?'文案与海报已生成，等待审核。':'交付物已准备好，等你审核。'):task.error||'旧版本生成已停止。');return task;
}
