function quoteValues() { const form=document.querySelector('#quote-form');return Object.fromEntries([...new FormData(form)].map(([k,v])=>[k,v===''?NaN:Number(v)])); }
function updateQuote() {
  const container=document.querySelector('#quote-result');if(!container)return;
  try{const values=quoteValues();const q=calculateQuote(values);const v=state.vehicles.find(v=>v.id===modalContext.vehicleId);container.innerHTML=`<div class="quote-result"><div class="quote-line"><span>车价 − 优惠 + 其他费用</span><strong>${moneyExact(q.subtotal,v.currency)}</strong></div><div class="quote-line"><span>假设税费</span><strong>${moneyExact(q.tax,v.currency)}</strong></div><div class="quote-line"><span>假设购车费用合计</span><strong>${moneyExact(q.total,v.currency)}</strong></div><div class="quote-total"><span>模拟月供 · ${values.months} 期</span><strong>${moneyExact(q.monthly,v.currency)}</strong></div></div>`;modalContext.quote={...q,values};}catch(error){container.innerHTML=`<div class="info-banner">${i('info')}${esc(error.message)}</div>`;modalContext.quote=null;}
}
function automationModal(id) {
  const a=state.automations.find(x=>x.id===id);modalContext={type:'automation',id};
  showModal(a?'编辑自动化':'让下一次关怀，有个好时间','按客户当地时间检查，生成的内容先交给你审核。',`<form id="automation-form"><div class="field-group"><label class="field-label" for="a-name">规则名称</label><input class="field" id="a-name" name="name" required maxlength="60" value="${esc(a?.name||'')}" placeholder="例如：高意向客户每周跟进"></div><div class="form-grid"><div class="field-group"><label class="field-label" for="a-segment">目标客户</label><select class="field" id="a-segment" name="segment">${[['hot','高意向客户'],['owners','已交付车主'],['dormant','14 天未联系的沉睡线索'],['all','全部潜在客户'],['family','家庭体验客群'],['charging','充电顾虑客群'],['fleet','企业采购客群'],['tradein','置换客群']].map(([key,value])=>`<option value="${key}" ${a?.segment===key?'selected':''}>${value}</option>`).join('')}</select></div><div class="field-group"><label class="field-label" for="a-kind">交付内容</label><select class="field" id="a-kind" name="kind">${scenarios.filter(s=>!['review','regional'].includes(s.id)).map(s=>`<option value="${s.id}" ${a?.kind===s.id?'selected':''}>${s.label}</option>`).join('')}</select></div><div class="field-group"><label class="field-label" for="a-cadence">重复间隔（天）</label><input class="field" id="a-cadence" name="cadence" type="number" required min="1" max="365" value="${a?.cadence||7}"></div><div class="field-group"><label class="field-label" for="a-hour">客户当地开始检查时间</label><select class="field" id="a-hour" name="hour">${Array.from({length:9},(_,index)=>index+9).map(hour=>`<option value="${hour}" ${hour===(a?.hour||10)?'selected':''}>${String(hour).padStart(2,'0')}:00</option>`).join('')}</select></div></div><div class="field-group"><label class="field-label" for="a-description">规则说明</label><textarea class="field" id="a-description" name="description" maxlength="500">${esc(a?.description||'根据最新客户记忆，准备一次有价值的联系。')}</textarea></div><div class="info-banner" style="margin:0">${i('shield')}<div>固定保护：校验渠道授权、最短 ${state.settings.minGapDays} 天联系间隔、09:00–18:00 当地时段；同类未处理草稿不会重复创建。<p>规则启用后，每分钟检查一次；页面关闭后不执行。</p></div></div></form>`,`${btn('取消','close-modal',null)}<button class="btn primary" form="automation-form" type="submit">${i('check')}保存并启用</button>`);
}
async function runAutomation(id,scheduled=false) {
  const rule=state.automations.find(a=>a.id===id);if(!rule?.enabled)return;const now=new Date();if(scheduled&&!ui.ai.ready)return;const candidates=state.customers.filter(c=>matchesSegment(c,rule.segment,now)&&(!scheduled||dueAutomation(rule,c,now))&&(!scheduled||!rule.lastAttempt?.[c.id]||now-new Date(rule.lastAttempt[c.id])>=900000));if(scheduled&&!candidates.length)return;
  let created=0;const details=[];const outcomes=[];
  for(const c of candidates){
    let check=contactEligibility(c,{now,minGapDays:state.settings.minGapDays});if(state.works.some(w=>w.customerId===c.id&&['paused','declined'].includes(w.status)))check={ok:false,reason:'客户工作已暂停'};
    if(check.ok&&rule.lastRuns?.[c.id]&&daysSince(rule.lastRuns[c.id],now)<rule.cadence)check={ok:false,reason:`尚未到 ${rule.cadence} 天重复周期`};
    if(check.ok&&state.tasks.some(t=>t.customerId===c.id&&t.kind===rule.kind&&['running','review','approved'].includes(t.status)))check={ok:false,reason:'已有同类待处理交付物'};
    if(check.ok){rule.lastAttempt??={};rule.lastAttempt[c.id]=now.toISOString();const task={id:uid('task'),title:c.name+' · '+kindLabel(rule.kind),customerId:c.id,kind:rule.kind,prompt:rule.name+'：'+rule.description,status:'running',automationId:id,createdAt:now.toISOString()};state.tasks.unshift(task);save();const a=await completeTask(task);if(a){rule.lastRuns??={};rule.lastRuns[c.id]=now.toISOString();created++;}else{check={ok:false,reason:task.error};}}
    const parts=localParts(c.timezone,now);rule.runs??={};if(check.ok)rule.runs[c.id]=`${parts.year}-${parts.month}-${parts.day}`;
    details.push(`${c.name}：${check.ok?'已生成待审核草稿':check.reason}`);outcomes.push({name:c.name,...check});
  }
  if(scheduled&&!created&&outcomes.every(o=>!o.reason?.includes('模型')&&!o.reason?.includes('Copilot')))return;
  rule.lastRun=now.toISOString();const summary=`检查 ${candidates.length} 位客户，生成 ${created} 份草稿。${details.join('；')||'暂无符合目标客群的客户。'}`;state.automationLog.unshift({id:uid('log'),name:rule.name,at:now.toISOString(),created,summary});state.automationLog=state.automationLog.slice(0,100);save();if(!document.querySelector('.modal'))render();
  if(!scheduled){showModal('本次自动化检查结果',esc(rule.name),`<div class="info-banner">${i('checkCircle')}<div><strong>生成 ${created} 份草稿，全部进入人工审核。</strong><p>已检查授权、当地时间、联系间隔和重复内容。</p></div></div>${outcomes.map(o=>`<div class="consent-row"><span>${esc(o.name)}</span><span class="badge ${o.ok?'green':'gray'}">${o.ok?'已生成草稿':esc(o.reason)}</span></div>`).join('')||'<p class="muted">暂无符合目标客群的客户。</p>'}`,`${btn('关闭','close-modal',null)}${btn('查看交付物','open-deliverables','arrow','primary')}`);}else if(created)toast(`自动化已准备 ${created} 份草稿，等待审核。`);
}
function knowledgeModal(id) {const k=state.knowledge.find(x=>x.id===id);modalContext={type:'knowledge',id};showModal(k?'编辑团队知识':'添加团队知识','让可确认的经验，成为下一份内容的参考。',`<form id="knowledge-form"><div class="field-group"><label class="field-label" for="k-title">知识标题</label><input class="field" id="k-title" name="title" required maxlength="80" value="${esc(k?.title||'')}"></div><div class="field-group"><label class="field-label" for="k-category">分类</label><select class="field" id="k-category" name="category">${['品牌指南','销售手册','工作规则','车型资料','售后服务'].map(category=>`<option ${k?.category===category?'selected':''}>${category}</option>`).join('')}</select></div><div class="field-group"><label class="field-label" for="k-body">内容与适用范围</label><textarea class="field" id="k-body" name="body" required maxlength="8000" style="min-height:210px">${esc(k?.body||'')}</textarea></div></form>`,`${btn('取消','close-modal',null)}<button class="btn primary" form="knowledge-form" type="submit">${i('check')}保存知识</button>`);}
function campaignModal() {modalContext={type:'campaign'};showModal('为你的市场，创造一次相遇','定义目标、客群和渠道，再一起准备活动内容。',`<form id="campaign-form"><div class="field-group"><label class="field-label" for="p-title">活动名称</label><input class="field" name="title" id="p-title" required maxlength="80" placeholder="Dubai · 秋季 SUV 试驾开放日"></div><div class="form-grid"><div class="field-group"><label class="field-label" for="p-market">目标市场</label><select class="field" name="market" id="p-market">${Object.entries(markets).filter(([key])=>key!=='all').map(([key,value])=>`<option value="${key}">${value}</option>`).join('')}</select></div><div class="field-group"><label class="field-label" for="p-channel">主要渠道</label><select class="field" name="channel" id="p-channel"><option>WhatsApp + Instagram</option><option>Email + Meta</option><option>Email + WhatsApp</option><option>Google + Website</option></select></div></div><div class="field-group"><label class="field-label" for="p-audience">目标客群</label><input class="field" name="audience" id="p-audience" required maxlength="100" placeholder="例如：近期关注家庭 SUV 的潜客"></div><div class="field-group"><label class="field-label" for="p-goal">活动目标</label><textarea class="field" name="goal" id="p-goal" required maxlength="500" placeholder="例如：邀请客户到店，体验后排空间与儿童座椅。"></textarea></div></form>`,`${btn('取消','close-modal',null)}<button class="btn primary" form="campaign-form" type="submit">${i('plus')}创建活动</button>`);}
function searchModal() {modalContext={type:'search'};showModal('找到下一步需要的资料','搜索客户、协作任务与交付物。',`<div class="search-field">${i('search')}<input class="field" id="global-search" data-input="global-search" placeholder="搜索 Sarah、充电、报价…" aria-label="全局搜索"></div><div id="global-results" class="search-results"></div>`,'','search-modal');updateGlobalSearch('');}
function updateGlobalSearch(query) {const q=query.toLowerCase();const results=[...state.customers.filter(c=>`${c.name} ${c.vehicle} ${c.need} ${c.tags.join(' ')}`.toLowerCase().includes(q)).map(c=>({type:'customer',id:c.id,title:c.name,sub:`客户画像 · ${c.vehicle} · ${c.city}`,icon:'users'})),...state.artifacts.filter(a=>`${a.title} ${a.sections.map(s=>s.text).join(' ')}`.toLowerCase().includes(q)).map(a=>({type:'artifact',id:a.id,title:a.title,sub:`交付物 · ${kindLabel(a.kind)}`,icon:'doc'})),...state.tasks.filter(t=>`${t.title} ${t.prompt}`.toLowerCase().includes(q)).map(t=>({type:'search-task',id:t.id,title:t.title,sub:'协作任务',icon:'spark'}))].slice(0,10);document.querySelector('#global-results').innerHTML=results.map(r=>`<button class="search-result" data-act="${r.type}" data-id="${r.id}"><span class="scenario-icon sage">${i(r.icon)}</span><span class="grow"><h3>${esc(r.title)}</h3><p>${esc(r.sub)}</p></span>${i('chevron')}</button>`).join('')||empty('没有找到结果','试试客户姓名、车型或工作关键词。');}
function download(content,name,type='text/markdown;charset=utf-8') {const url=URL.createObjectURL(new Blob([content],{type}));const link=document.createElement('a');link.href=url;link.download=name;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),3000);toast('文件已准备下载。');}
async function copyText(text) {try{await navigator.clipboard.writeText(text);toast('客户话术已复制，可审核后粘贴使用。');}catch{showModal('复制客户话术','浏览器未授予剪贴板权限，请选中内容手动复制。',`<textarea class="field" style="min-height:250px" readonly>${esc(text)}</textarea>`,btn('关闭','close-modal',null));}}

document.addEventListener('click',async event=>{
  if(event.target.matches('[data-overlay]')){closeModal();return;}
  const el=event.target.closest('[data-act]');if(!el)return;const {act,id,kind}=el.dataset;
  if(await coworkUI.handleAction(act,el.dataset))return;
  if(await handleExtendedAction(act,el.dataset))return;
  if(act==='close-modal'){closeModal();return;}
  if(act==='mobile-menu'){ui.mobileOpen=true;render();return;}if(act==='mobile-close'){ui.mobileOpen=false;render();return;}
  if(act==='settings'){closeModal();navigate('settings');return;}
  if(act==='search'){searchModal();return;}
  if(act==='notifications'){closeModal();navigate('inbox');return;}
  if(act==='open-deliverables'){closeModal();ui.docFilter='review';navigate('deliverables');return;}
  if(act==='customer'){customerModal(id);return;}
  if(act==='edit-memory'){const c=getCustomer(el.dataset.customer),m=c.memories.find(m=>m.id===id);if(!m)return;modalContext={type:'memory-edit',customerId:c.id,id};showModal('纠正客户记忆','更正后相关草稿会失效，历史内容不再参与生成。',`<form id="memory-edit-form"><label class="field-label" for="memory-value">正确的记录</label><textarea class="field" name="text" id="memory-value" required maxlength="2000">${esc(m.text)}</textarea><label class="field-label" for="memory-type">记录性质</label><select class="field" name="type" id="memory-type"><option value="record">已记录事实</option><option value="inference" ${m.type==='inference'?'selected':''}>待核实判断</option></select><label class="checkbox cw-confirm"><input name="remove" type="checkbox">不再使用这条记忆</label></form>`,'<button class="btn primary" form="memory-edit-form" type="submit">保存纠正</button>');return;}
  if(act==='new-customer'){customerForm();return;}if(act==='edit-customer'){customerForm(id);return;}
  if(act==='new-task'){taskModal();return;}
  if(act==='scenario'){const map={followup:'c1',quote:'c3',campaign:'c2',aftersales:'c7',testdrive:'c1',intake:'c5',relationship:'c7',review:'c2',regional:'c1'};taskModal(id,scopedCustomers().find(c=>c.id===map[id])?.id||scopedCustomers()[0]?.id||'c1');return;}
  if(act==='suggest'){const s=scenarios.find(s=>s.id===id);document.querySelector('#home-prompt').value=s.prompt;document.querySelector('#home-prompt').dataset.kind=id;const map={followup:'c1',quote:'c3',campaign:'c2',aftersales:'c7'};document.querySelector('#home-customer').value=map[id]||'c1';document.querySelector('#home-prompt').focus();return;}
  if(act==='home-run'){const field=document.querySelector('#home-prompt');const prompt=field.value.trim();if(!prompt){toast('写下协作要求，或选择下方的场景灵感。');field.focus();return;}const chosen=document.querySelector('#home-customer').value;const k=field.dataset.kind||(/区域|跨店|regional/i.test(prompt)?'regional':/复盘|转化|review/i.test(prompt)?'review':/新线索|交接|intake/i.test(prompt)?'intake':/老客|关系|relationship/i.test(prompt)?'relationship':/报价|选车|月供|quote|finance/i.test(prompt)?'quote':/活动|营销|campaign/i.test(prompt)?'campaign':/售后|保养|关怀|aftersales/i.test(prompt)?'aftersales':/邀约|试驾预约|test drive/i.test(prompt)?'testdrive':'followup');return startRun(k,chosen,prompt);}
  if(act==='customer-run'){const c=getCustomer(id);return startRun(kind,id,`为 ${c.name} 准备${kindLabel(kind)}。请结合已记录的需求与顾虑，重点推进：${c.next}。`);}
  if(act==='role'){ui.role=id;render();return;}
  if(act==='cancel-task'){const t=state.tasks.find(t=>t.id===id);if(t){t.status='cancelled';t.error='已停止本次生成。';runningRequests.get(id)?.abort();save();render();}return;}
  if(act==='select-task'||act==='search-task'){ui.taskId=id;closeModal();navigate('workspace');return;}
  if(act==='refine-task'){const input=document.querySelector('#task-refine');if(!input.value.trim()){input.focus();toast('请补充这次协作的具体要求。');return;}const task=state.tasks.find(t=>t.id===ui.taskId);return startRun(task.kind,task.customerId,input.value.trim(),{previousArtifact:state.artifacts.find(a=>a.id===task.artifactId),preferredVehicleId:task.preferredVehicleId,campaignId:task.campaignId,workId:task.workId,needsPoster:task.needsPoster,cohort:task.cohort});}
  if(act==='artifact'){artifactModal(id);return;}
  if(act==='artifact-edit'){artifactModal(id,true);return;}
  if(act==='artifact-preview'){saveArtifactEdits(id);artifactModal(id);return;}
  if(act==='save-artifact'){saveArtifactEdits(id);artifactModal(id);toast('修改已保存，交付物已重新进入待审核。');return;}
  if(act==='copy-artifact'){if(modalContext.edit)saveArtifactEdits(id);const a=state.artifacts.find(a=>a.id===id);const section=a.sections.find(s=>s.audience==='customer')||a.sections.find(s=>/English|العربية|Deutsch/.test(s.label));if(!section){toast('没有标记为对客内容的段落，请先编辑交付物。');return;}await copyText(section.text);return;}
  if(act==='download-artifact'){if(modalContext.edit)saveArtifactEdits(id);const a=state.artifacts.find(a=>a.id===id);download(artifactText(a),`${a.title}.md`);return;}
  if(act==='approve-artifact'){const a=state.artifacts.find(a=>a.id===id);if(!isArtifactCurrent(state,a)){toast('客户资料已变化，请使用最新工作包重新生成。');return;}a.status='approved';a.approvedAt=new Date().toISOString();state.tasks.filter(t=>t.artifactId===id).forEach(t=>t.status='approved');save();render();artifactModal(id);toast('审核已记录。可复制或导出后使用。');return;}
  if(act==='record-contact'){const a=state.artifacts.find(a=>a.id===id);const c=getCustomer(a.customerId);if(!isArtifactCurrent(state,a)||a.status!=='approved'){toast('请先审核当前有效版本。');return;}if(c.serviceIssue?.status==='open'&&a.kind!=='aftersales'){toast('先处理未结服务问题，当前促销暂停。');return;}if(!c.consent[c.channel]){toast('请先在客户画像中补充真实的渠道授权记录。');return;}modalContext={type:'contact',artifactId:id};showModal('记录一次手动联系','只有你已在外部渠道实际联系客户后，才保存这条记录。',`<form id="contact-form"><p style="font-size:12px;color:#839473;margin-bottom:18px">客户：${esc(c.name)} · 渠道：${c.channel}<br>本操作仅更新沟通记录，不发送消息。</p><div class="field-group"><label class="field-label" for="contact-note">本次沟通与客户反馈</label><textarea class="field" id="contact-note" name="note" required maxlength="1000" placeholder="记录已发送的内容与客户的真实反馈。"></textarea></div><label class="checkbox"><input type="checkbox" required name="confirmed">我确认已通过上述渠道实际联系客户。</label></form>`,`${btn('取消','close-modal',null)}<button class="btn primary" form="contact-form" type="submit">${i('check')}保存沟通记录</button>`);return;}
  if(act==='doc-filter'){ui.docFilter=id;render();return;}
  if(act==='calculator'){calculatorModal(id,el.dataset.customer);return;}
  if(act==='export-quote'){if(!modalContext.quote){toast('请先修正费用参数。');return;}const v=state.vehicles.find(v=>v.id===modalContext.vehicleId);const q=modalContext.quote;download(`${v.name} — 假设购车费用试算\n\n市场：${markets[v.market]}\n币种：${v.currency}\n车价：${moneyExact(q.values.price,v.currency)}\n假设优惠：${moneyExact(q.values.discount,v.currency)}\n假设其他费用：${moneyExact(q.values.fee,v.currency)}\n假设税率：${q.values.taxRate}%\n假设税费：${moneyExact(q.tax,v.currency)}\n合计：${moneyExact(q.total,v.currency)}\n假设首付：${moneyExact(q.values.downPayment,v.currency)}\n假设 APR：${q.values.apr}%\n贷款期数：${q.values.months}\n模拟月供：${moneyExact(q.monthly,v.currency)}\n\n以上仅为假设试算。实际税费、税基、优惠、费用、授信与置换价值均需门店及金融机构确认，不构成正式报价。`,`${v.name}-费用试算.md`);return;}
  if(act==='match-vehicle'){const v=state.vehicles.find(v=>v.id===id);const list=state.customers.filter(c=>c.market===v.market&&c.currency===v.currency&&!['已成交','售后维护'].includes(c.stage));showModal(`${esc(v.name)} · 适合谁？`,'仅匹配同市场、同币种且正在购车的客户。',list.map(c=>`<div class="consent-row"><div class="customer-cell">${avatar(c)}<div><div class="customer-name">${esc(c.name)}</div><div class="customer-sub">${v.price<=c.budget[1]?'车价在预算上限内，总费用待确认':'车价超出当前预算'} · ${esc(c.vehicle)}</div></div></div>${btn('准备方案','vehicle-customer-run','arrow','soft sm',`data-id="${c.id}" data-vehicle="${v.id}"`)}</div>`).join('')||empty('暂时没有匹配客户','新增同市场客户后可在此匹配。'),btn('关闭','close-modal',null));return;}
  if(act==='vehicle-customer-run'){const v=state.vehicles.find(v=>v.id===el.dataset.vehicle);const c=getCustomer(id);return startRun('quote',id,`为 ${c.name} 准备方案，重点比较 ${v.name} 与客户原意向车型 ${c.vehicle}，核实预算和本地配置。`,{preferredVehicleId:v.id});}
  if(act==='new-campaign'){campaignModal();return;}
  if(act==='campaign-package'){const p=state.campaigns.find(p=>p.id===id);const c=state.customers.find(c=>c.market===p.market&&!['已成交','售后维护'].includes(c.stage))||state.customers.find(c=>c.market===p.market);if(!c){toast('请先新增该市场客户，以便准备本地化内容。');return;}p.status='内容准备';save();return startRun('campaign',c.id,`活动：${p.title}\n目标：${p.goal}\n客群：${p.audience}\n渠道：${p.channel}。准备活动简报、多语言内容、可渲染的海报文案和执行计划。`,{campaignId:id});}
  if(act==='new-automation'){automationModal();return;}if(act==='edit-automation'){automationModal(id);return;}
  if(act==='toggle-automation'){const a=state.automations.find(a=>a.id===id);a.enabled=!a.enabled;save();render();toast(a.enabled?'自动化已启用，页面打开时检查日程。':'自动化已暂停。');return;}
  if(act==='run-automation'){return runAutomation(id);}
  if(act==='new-knowledge'){knowledgeModal();return;}if(act==='edit-knowledge'){knowledgeModal(id);return;}
  if(act==='integration'){const name=el.dataset.name;showModal(`${esc(name)} · 接入说明`,'该业务渠道尚未连接。',`<div class="onboarding-list">${[['准备业务账户','使用门店授权的业务账户，确认需要同步的市场与数据范围。'],['连接后台服务','正式版需要服务端保存凭据、执行请求，并处理回调和权限。'],['用少量真实数据验证','先验证客户匹配、授权、时区和审核流程，再开放团队使用。']].map(([t,p],n)=>`<div class="onboarding-item"><span class="onboarding-number">${n+1}</span><div><strong>${t}</strong><p>${p}</p></div></div>`).join('')}</div><div class="info-banner" style="margin:25px 0 0">${i('info')}本原型不收集访问密钥，也不会伪装成已连接。</div>`,btn('了解了','close-modal','check','primary'));return;}
  if(act==='guide'){showModal('欢迎来到 Motive','从客户的故事出发，一起完成下一步。',`<div class="onboarding-list">${[['认识客户','在客户与画像中查看 Sarah 的预算、儿童座椅和公寓充电顾虑，也可以新增客户或记忆。'],['开始协作','选择个性化跟进、选车报价、试驾邀约、营销活动或售后关怀。'],['带走成果','在交付物中编辑、审核、复制客户话术，或导出完整方案。'],['安排下一次关怀','创建自动化，设置客群和当地时间，检查后将内容放入审核队列。']].map(([t,p],n)=>`<div class="onboarding-item"><span class="onboarding-number">${n+1}</span><div><strong>${t}</strong><p>${p}</p></div></div>`).join('')}</div><div class="info-banner" style="margin:24px 0 0">${i('info')}客户与车源初始数据为示例。模型状态会明确显示；消息发送渠道和后台日程尚未连接。营销活动同时支持文案与可导出的海报。</div>`,btn('开始体验','close-modal','arrow','primary'));return;}
});
function saveArtifactEdits(id) {const a=state.artifacts.find(a=>a.id===id);let changed=false;document.querySelectorAll('[data-section]').forEach(el=>{if(a.sections[Number(el.dataset.section)].text!==el.value){a.sections[Number(el.dataset.section)].text=el.value;changed=true;}});if(changed){delete a.approvedAt;a.status=a.staleReason?'stale':'review';a.updatedAt=new Date().toISOString();state.tasks.filter(t=>t.artifactId===id).forEach(t=>t.status='review');save();render();}}
document.addEventListener('submit',async event=>{
  if(event.target.id==='poster-form'){event.preventDefault();const a=savePosterEdits();if(a){render();posterModal(a.id);toast('海报已保存。');}return;}
  const form=event.target;if(form.id.startsWith('cw-')){event.preventDefault();return coworkUI.handleSubmit(form,Object.fromEntries(new FormData(form)));}
  if(!['memory-edit-form','task-form','customer-form','memory-form','automation-form','knowledge-form','campaign-form','settings-form','contact-form'].includes(form.id))return;event.preventDefault();const data=Object.fromEntries(new FormData(form));
  if(form.id==='memory-edit-form'){const c=getCustomer(modalContext.customerId),m=c.memories.find(m=>m.id===modalContext.id);if(!m)return;const previous=m.text;m.superseded=true;if(!data.remove)c.memories.push({id:uid('memory'),text:data.text.trim(),type:data.type,source:state.settings.operator+' · 更正记录',at:new Date().toISOString()});if(c.need.includes(previous))c.need=c.need.replace(previous,data.remove?'需求待核实':data.text.trim());if(c.concern.includes(previous))c.concern=c.concern.replace(previous,data.remove?'待重新核实':data.text.trim());updateCustomerContext(state,c.id,'纠正客户记忆');save();render();customerModal(c.id);toast('已更正，后续生成不再引用旧记忆。');return;}
  if(form.id==='task-form'){return startRun(data.kind,data.customerId,data.prompt.trim());}
  if(form.id==='memory-form'){const c=getCustomer(form.dataset.id);if(!data.memory.trim())return;c.memories.push({text:data.memory.trim(),source:`${state.settings.operator} · 手动记录 · ${dateText(new Date())}`,id:uid('memory'),type:'record',at:new Date().toISOString()});updateCustomerContext(state,c.id,'新增客户记忆');save();customerModal(c.id);toast('已记住，下次协作会带上这条信息。');return;}
  if(form.id==='customer-form'){
    if(data.stage==='已约试驾'&&!state.works.some(w=>w.customerId===modalContext.id&&w.reservation)){toast('请通过客户工作登记预约回执。');return;}
    if(Number(data.budgetMax)<Number(data.budgetMin)){toast('预算上限不能低于下限。');return;}
    const currency={US:'USD',AE:'AED',GB:'GBP',DE:'EUR'}[data.market];const old=modalContext.id?getCustomer(modalContext.id):null;
    if(data.channel==='Email'&&!data.email.trim()||data.channel==='WhatsApp'&&!data.contact.trim()){toast('请填写首选联系渠道的邮箱或电话号码。');return;}
    const c={...(old||{id:uid('c'),color:['peach','sage','blue','lavender'][state.customers.length%4],intent:50,source:'手动新增',owner:state.settings.operator,lastContact:null,role:'新客户 · 待了解',tags:['新客户'],memories:[],timeline:[]}),name:data.name.trim(),initials:data.name.trim().split(/\s+/).slice(0,2).map(n=>n[0]).join('').toUpperCase(),market:data.market,city:data.city.trim(),timezone:data.timezone,language:data.language,currency,stage:data.stage,budgetUnknown:false,budget:[Number(data.budgetMin),Number(data.budgetMax)],vehicle:data.vehicle.trim(),channel:data.channel,contact:data.contact.trim(),email:data.email.trim(),need:data.need.trim(),concern:data.concern.trim()||'待进一步确认',next:data.next.trim()||'确认购车需求',consent:{WhatsApp:!!data.consentWhatsApp,Email:!!data.consentEmail}};
    if(!old){c.memories.push({text:c.need,source:`${state.settings.operator} · 新增客户资料`});c.timeline.push({title:'建立客户画像',body:'手动录入客户需求与联系偏好。',at:new Date().toISOString()});state.customers.unshift(c);}else{state.customers[state.customers.findIndex(x=>x.id===c.id)]=c;if(JSON.stringify(old.consent)!==JSON.stringify(c.consent))c.timeline.unshift({title:'更新联系授权',body:`WhatsApp：${c.consent.WhatsApp?'已记录同意':'未授权'}；Email：${c.consent.Email?'已记录同意':'未授权'}。由 ${state.settings.operator} 手动更新，来源为表单确认。`,at:new Date().toISOString()});}
    if(old)updateCustomerContext(state,c.id,'编辑客户画像或联系授权');else initializeCowork(state);save();render();customerModal(c.id);toast('客户画像与相关工作已更新。');return;
  }
  if(form.id==='automation-form'){const old=state.automations.find(a=>a.id===modalContext.id);const a={...(old||{id:uid('a'),createdAt:new Date().toISOString(),lastRun:null}),name:data.name.trim(),description:data.description.trim(),segment:data.segment,kind:data.kind,cadence:Number(data.cadence),hour:Number(data.hour),enabled:true};if(old)state.automations[state.automations.findIndex(x=>x.id===old.id)]=a;else state.automations.push(a);save();closeModal();navigate('automations');toast('规则已保存，客户当地合适时间开始检查。');return;}
  if(form.id==='knowledge-form'){const old=state.knowledge.find(k=>k.id===modalContext.id);const k={id:old?.id||uid('k'),title:data.title.trim(),category:data.category,body:data.body.trim(),updatedAt:new Date().toISOString()};if(old)state.knowledge[state.knowledge.findIndex(x=>x.id===old.id)]=k;else state.knowledge.push(k);save();closeModal();render();toast('团队知识已更新，新交付物将附上最新参考。');return;}
  if(form.id==='campaign-form'){state.campaigns.unshift({id:uid('p'),title:data.title.trim(),market:data.market,channel:data.channel,audience:data.audience.trim(),goal:data.goal.trim(),status:'筹备中',color:'sage'});save();closeModal();ui.market='all';navigate('campaigns');toast('活动已创建，可以开始准备内容包。');return;}
  if(form.id==='settings-form'){state.settings={...state.settings,name:data.name.trim(),operator:data.operator.trim(),role:data.role,minGapDays:Number(data.minGapDays)};save();render();toast('工作区设置已保存。');return;}
  if(form.id==='contact-form'){if(!data.confirmed){toast('请确认已实际联系。');return;}const a=state.artifacts.find(a=>a.id===modalContext.artifactId);const c=getCustomer(a.customerId);if(!isArtifactCurrent(state,a)||!c.consent[c.channel]||a.status!=='approved'){toast('资料或授权已变化，请重新检查。');return;}const now=new Date().toISOString();c.lastContact=now;c.timeline.unshift({title:`手动 ${c.channel} 联系`,body:data.note.trim(),at:now});a.status='contacted';a.contactedAt=now;state.tasks.filter(t=>t.artifactId===a.id).forEach(t=>t.status='contacted');save();closeModal();render();toast('已记录实际联系时间，自动化会遵守新的联系间隔。');return;}
});
document.addEventListener('change',event=>{const target=event.target;const key=target.dataset.change;if(key){ui[key]=target.value;render();}if(target.dataset.input==='poster')updatePosterPreview();if(target.id==='c-market'){const defaults={US:['America/Chicago','en'],AE:['Asia/Dubai','ar'],GB:['Europe/London','en'],DE:['Europe/Berlin','de']}[target.value];document.querySelector('#c-timezone').value=defaults[0];document.querySelector('#c-language').value=defaults[1];}if(target.id==='task-kind'||target.id==='task-customer'){const c=getCustomer(document.querySelector('#task-customer').value);const kind=document.querySelector('#task-kind').value;document.querySelector('#task-prompt').value=`为 ${c.name} 准备${kindLabel(kind)}，结合已记录的客户需求与顾虑。重点推进：${c.next}。`;}if(target.id==='home-customer'){delete document.querySelector('#home-prompt').dataset.kind;}});
document.addEventListener('input',event=>{const target=event.target;if(target.dataset.input==='customer-search'){ui.query=target.value;const list=scopedCustomers().filter(c=>(ui.stage==='all'||c.stage===ui.stage)&&`${c.name} ${c.vehicle} ${c.city} ${c.tags.join(' ')}`.toLowerCase().includes(ui.query.toLowerCase()));document.querySelector('#customer-table').innerHTML=customerTable(list);}if(target.dataset.input==='global-search')updateGlobalSearch(target.value);if(target.dataset.input==='quote')updateQuote();if(target.dataset.input==='poster')updatePosterPreview();if(target.id==='home-prompt')delete target.dataset.kind;});
document.addEventListener('keydown',event=>{if((event.metaKey||event.ctrlKey)&&event.key.toLowerCase()==='k'){event.preventDefault();searchModal();return;}if(event.key==='Escape'){closeModal();if(ui.mobileOpen){ui.mobileOpen=false;render();}return;}if(event.key==='Enter'&&event.target.matches('[data-act][role=button],tr[data-act]')){event.preventDefault();event.target.click();return;}if(event.key==='Enter'&&event.target.id==='task-refine'){event.preventDefault();document.querySelector('[data-act=refine-task]').click();return;}const modal=document.querySelector('.modal');if(event.key==='Tab'&&modal){const focusable=[...modal.querySelectorAll('button:not([disabled]),input:not([disabled]),textarea:not([disabled]),select:not([disabled]),a[href]')].filter(e=>e.offsetParent!==null);const first=focusable[0],last=focusable[focusable.length-1];if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}});
window.addEventListener('hashchange',()=>{ui.page=location.hash.slice(1)||'home';ui.mobileOpen=false;closeModal();render();window.scrollTo(0,0);});
render();
let checkingAutomations=false;setInterval(async()=>{if(document.hidden||checkingAutomations)return;const morning=createMorningBrief(state);if(morning)save();if(!ui.ai.ready)return;checkingAutomations=true;try{for(const rule of state.automations.filter(a=>a.enabled))await runAutomation(rule.id,true);}finally{checkingAutomations=false;}},60000);
refreshAIStatus();
